patterns.css:
:root{
    --bone:#f3efe7; --ink:#1f2937; --rust:#9a3412; --muted:#6b6257; --line:#cfc7b8;
    --ease:cubic-bezier(.65,0,.35,1); --dur:480ms;
  }
  *{box-sizing:border-box}
  body{margin:0;background:var(--bone);color:var(--ink);font-family:"Arial Narrow",Arial,sans-serif;line-height:1.5}
  h1,h2,h3{font-family:"Arial Black",Arial,sans-serif;text-transform:uppercase;line-height:.9;letter-spacing:-.04em;margin:0}
  a{color:inherit;text-decoration:none}
  .page{width:min(1240px,95vw);margin:0 auto;border-left:1px solid var(--line);border-right:1px solid var(--line)}
  .masthead{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:24px;padding:16px 24px;border-bottom:3px double var(--ink)}
  .masthead .logo{font-family:"Arial Black",Arial,sans-serif;font-size:34px;letter-spacing:-.06em;text-transform:uppercase}
  .masthead .logo span{color:var(--rust)}
  .masthead nav{display:flex;gap:20px;font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted)}
  .masthead nav a:hover{color:var(--rust)}
  .masthead .issue{text-align:right;font-size:9px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted);line-height:1.7}
  .masthead .issue b{display:block;color:var(--rust);font-size:13px}
  .cover{display:grid;grid-template-columns:1.1fr .9fr;border-bottom:1px solid var(--line)}
  .cover-copy{padding:34px 30px;border-right:1px solid var(--line);position:relative;overflow:hidden}
  .cover-copy::after{content:"T";position:absolute;right:-10px;bottom:-80px;font-family:"Arial Black",Arial,sans-serif;font-size:360px;line-height:1;color:#9a34120d;pointer-events:none}
  .kicker{font-size:9px;letter-spacing:.3em;text-transform:uppercase;color:var(--rust)}
  .cover-copy h1{font-size:clamp(54px,7vw,104px);margin:12px 0 14px;max-width:11ch}
  .cover-copy h1 span{color:var(--rust)}
  .cover-copy .lead{max-width:42ch;font-family:Georgia,serif;font-size:14px;line-height:1.7;color:var(--muted);margin:0 0 20px}
  .cover-lines{display:grid;gap:7px;border-top:1px solid var(--line);padding-top:14px;max-width:360px}
  .cover-lines a{display:flex;justify-content:space-between;gap:12px;font-size:10px;letter-spacing:.1em;text-transform:uppercase;padding:5px 0;border-bottom:1px solid #cfc7b888}
  .cover-lines a b{color:var(--rust);font-weight:400}
  .cover-art{background:var(--rust);position:relative;overflow:hidden;min-height:420px}
  .cover-art::before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(90deg,#0000 0 18px,#f3efe726 18px 19px)}
  .cover-art .caption{position:absolute;left:18px;bottom:16px;color:var(--bone);font-size:9px;letter-spacing:.24em;text-transform:uppercase}
  .cover-art .folio{position:absolute;right:16px;top:14px;color:#f3efe7cc;font-family:"Arial Black",Arial,sans-serif;font-size:54px;line-height:1}
  .toc{display:grid;grid-template-columns:1fr 1fr;border-bottom:1px solid var(--line)}
  .toc .intro{padding:26px 30px;border-right:1px solid var(--line)}
  .toc .intro h2{font-size:30px;max-width:14ch}
  .toc .intro p{font-family:Georgia,serif;font-size:12px;color:var(--muted);margin:10px 0 0;max-width:38ch}
  .toc .list{padding:20px 26px;display:grid;align-content:center}
  .toc .item{display:grid;grid-template-columns:28px 1fr auto;gap:12px;align-items:baseline;padding:10px 0;border-bottom:1px solid var(--line);font-size:10px;letter-spacing:.08em;text-transform:uppercase}
  .toc .item:first-child{border-top:1px solid var(--line)}
  .toc .item b{font-family:"Arial Black",Arial,sans-serif;font-size:15px;color:var(--rust)}
  .toc .item small{font-family:Georgia,serif;font-size:10px;color:var(--muted);text-transform:none;letter-spacing:0}
  .article{display:grid;grid-template-columns:1.2fr .8fr;gap:0;border-bottom:1px solid var(--line)}
  .article .body{padding:28px 30px;border-right:1px solid var(--line);column-count:2;column-gap:24px}
  .article .body h2{font-size:34px;column-span:all;margin-bottom:10px;max-width:16ch}
  .article .body p{font-family:Georgia,serif;font-size:12.5px;line-height:1.7;color:var(--muted);margin:0 0 12px}
  .article .side{padding:24px;display:flex;flex-direction:column;gap:14px}
  .article .side .swatch{height:120px;background:var(--ink);position:relative;overflow:hidden}
  .article .side .swatch::after{content:"";position:absolute;inset:0;background:repeating-linear-gradient(45deg,#0000 0 10px,#f3efe71f 10px 11px)}
  .article .side .swatch.alt{background:var(--rust)}
  .article .side .cap{font-size:9px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted)}
  .looks{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid var(--line)}
  .look{padding:18px;border-right:1px solid var(--line);min-height:200px;display:flex;flex-direction:column;justify-content:space-between;transition:background var(--dur) var(--ease)}
  .look:last-child{border-right:0}
  .look:hover{background:#fffaf2}
  .look .no{font-size:9px;letter-spacing:.2em;color:var(--rust)}
  .look h3{font-size:22px;margin-top:8px}
  .look .fig{height:74px;background:#d6cdbd;margin-top:10px;position:relative;overflow:hidden}
  .look:nth-child(2) .fig{background:var(--rust)}
  .look:nth-child(3) .fig{background:var(--ink)}
  .look:nth-child(4) .fig{background:#b9ae9c}
  .look .fig::after{content:"";position:absolute;inset:0;background:repeating-linear-gradient(45deg,#0000 0 9px,#f3efe71f 9px 10px)}
  .look .go{display:flex;justify-content:space-between;margin-top:10px;font-size:9px;letter-spacing:.16em;text-transform:uppercase}
  footer{display:flex;justify-content:space-between;padding:14px 24px;font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted)}
  .reveal{opacity:0;clip-path:inset(0 0 100% 0);transition:opacity var(--dur) var(--ease),clip-path var(--dur) var(--ease)}
  .reveal.on{opacity:1;clip-path:inset(0)}
  @media (max-width:900px){.masthead nav{display:none}.cover{grid-template-columns:1fr}.cover-copy{border-right:0}.cover-art{min-height:300px}
    .toc,.article{grid-template-columns:1fr}.toc .intro,.article .body{border-right:0;border-bottom:1px solid var(--line)}
    .article .body{column-count:1}.looks{grid-template-columns:1fr 1fr}.look:nth-child(2){border-right:0}}
