  .frames{display:flex;gap:14px;padding:0 28px 18px;overflow-x:auto;scroll-snap-type:x mandatory;max-width:1240px;margin:0 auto}
  .frame{flex:0 0 300px;scroll-snap-align:start;position:relative}
  .frame .art{height:330px;background:linear-gradient(150deg,#6b2a3c,#2b141d);position:relative;overflow:hidden}
  .frame:nth-child(2) .art{background:linear-gradient(150deg,#c9a184,#7a4a35)}
