  .frame .art::after{content:"";position:absolute;inset:0;background:repeating-linear-gradient(0deg,#0000 0 46px,#0000000d 46px 47px)}
  .frame .num{position:absolute;left:10px;top:8px;color:#f5f1eacc;font-family:"Didot",Georgia,serif;font-size:22px}
