  .credits-block .meta span{font-size:8px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted)}
  .quote{max-width:1180px;margin:0 auto;padding:30px 28px;text-align:center}
  .quote blockquote{margin:0 auto;max-width:760px;font-family:"Didot",Georgia,serif;font-size:clamp(24px,3vw,38px);line-height:1.22}
  .quote cite{display:block;margin-top:10px;font-family:"Gill Sans",sans-serif;font-style:normal;font-size:8.5px;letter-spacing:.24em;text-transform:uppercase;color:var(--muted)}
  footer{display:flex;justify-content:space-between;padding:14px 28px;border-top:1px solid var(--line);font-size:8.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted)}
  .reveal{opacity:0;transform:translateY(22px);transition:opacity var(--dur) var(--ease),transform var(--dur) var(--ease)}
  .reveal.on{opacity:1;transform:none}
  @media (max-width:900px){.cover .inner{grid-template-columns:1fr}.cover .stamp{display:none}.credits-block{grid-template-columns:1fr}
