  body{margin:0;background:var(--ivory);color:var(--ink);font-family:"Palatino Linotype","Book Antiqua",Palatino,serif;line-height:1.65}
  h1,h2,h3{font-family:"Garamond","Times New Roman",serif;font-weight:400;line-height:1.1;margin:0}
  a{color:inherit;text-decoration:none}
  .sheet{width:min(1080px,92vw);margin:26px auto;background:var(--paper);border:1px solid var(--line);box-shadow:0 30px 70px -50px #1d2b26;position:relative}
  .sheet::before{content:"";position:absolute;inset:10px;border:1px solid #d9d1bd88;pointer-events:none}
  .top{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:18px 34px;border-bottom:3px double var(--line);font-size:9px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted)}
  .top .brand{display:flex;align-items:center;gap:9px;font-family:"Garamond",serif;font-size:18px;letter-spacing:.26em;color:var(--forest);text-transform:uppercase}
  .top .brand svg{color:var(--brass)}
  .top nav{display:flex;gap:20px}
  .top nav a:hover{color:var(--forest)}
  .doc{display:grid;grid-template-columns:200px minmax(0,1fr);gap:0}
  .margin{padding:34px 24px;border-right:1px solid var(--line);display:flex;flex-direction:column;gap:22px}
  .margin .seal{display:grid;justify-items:center;gap:6px;text-align:center;color:var(--forest)}
  .margin .seal b{font-family:"Garamond",serif;font-size:13px;letter-spacing:.24em;text-transform:uppercase;font-weight:400}
  .margin .seal small{font-size:8px;letter-spacing:.24em;text-transform:uppercase;color:var(--brass)}
  .margin .meta{border-top:1px solid var(--line);padding-top:14px;font-size:9px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);display:grid;gap:8px}
  .margin .meta b{color:var(--forest);font-weight:400}
  .body{padding:38px 40px 34px}
  .body .date{font-size:10px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted)}
  .body h1{font-size:clamp(38px,4.8vw,64px);color:var(--forest);margin:12px 0 16px;max-width:16ch}
  .body h1 em{font-style:italic;color:var(--brass)}
  .body .lead{font-size:15px;color:var(--muted);max-width:58ch;margin:0 0 24px}
  .clauses{border-top:1px solid var(--line);margin-bottom:24px}
