  .btn.solid{background:var(--forest);color:var(--ivory)}
  .btn:hover{background:var(--forest);color:var(--ivory)}
  footer{display:flex;justify-content:space-between;padding:14px 34px;border-top:1px solid var(--line);font-size:8px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted)}
