  .btn.lime{border-color:var(--lime);color:var(--lime)}
  .btn.lime:hover{background:var(--lime);color:var(--void);box-shadow:0 0 24px #a3e63555}
  .panel{background:#0a111bcc;border:1px solid var(--line);border-radius:var(--r);padding:18px;position:relative;overflow:hidden}
  .panel::before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(0deg,#0000 0 3px,#22d3ee08 3px 4px);pointer-events:none}
  .panel-head{display:flex;justify-content:space-between;font-size:9px;letter-spacing:.18em;color:var(--muted);border-bottom:1px solid var(--line);padding-bottom:10px;margin-bottom:14px}
  .panel-head b{color:var(--cyan)}
  .diag{height:150px;border:1px solid var(--line);position:relative;margin-bottom:14px;background:
    linear-gradient(90deg,#18324466 1px,#0000 1px),linear-gradient(#18324466 1px,#0000 1px);background-size:20px 20px}
  .diag svg{position:absolute;inset:0;width:100%;height:100%}
  .diag .ping{position:absolute;left:24%;top:38%;width:7px;height:7px;background:var(--lime);border-radius:50%;box-shadow:0 0 14px var(--lime)}
  .metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
  .metric{border:1px solid var(--line);padding:10px}
  .metric b{display:block;color:var(--cyan);font-size:19px}
  .metric span{font-size:8px;letter-spacing:.14em;color:var(--muted);text-transform:uppercase}
  .strip{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin-bottom:54px}
  .strip div{padding:16px 20px;border-right:1px solid var(--line);font-size:10px;letter-spacing:.1em;color:var(--muted);display:flex;gap:9px;align-items:center}
  .strip div:last-child{border-right:0}
  .strip svg{color:var(--lime);flex:none}
  .section{padding-bottom:58px}
  .section-head{display:flex;justify-content:space-between;align-items:end;margin-bottom:18px}
  .section-head h2{font-size:28px}
  .section-head span{font-size:9px;letter-spacing:.18em;color:var(--muted)}
  .cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
  .card{border:1px solid var(--line);background:#0a111b;padding:20px;position:relative;
    transition:border-color var(--dur) var(--ease),transform var(--dur) var(--ease),box-shadow var(--dur) var(--ease)}
  .card:hover{border-color:var(--cyan);transform:translateY(-3px);box-shadow:0 0 0 1px #22d3ee33,0 18px 40px -30px #22d3ee}
  .card .ico{width:36px;height:36px;border:1px solid var(--line);display:grid;place-items:center;color:var(--cyan);margin-bottom:16px}
  .card h3{font-size:16px;margin-bottom:6px}
  .card p{font-size:11px;color:var(--muted);margin:0 0 16px}
  .card .read{font-size:9px;letter-spacing:.18em;color:var(--lime);text-transform:uppercase}
  .log{border:1px solid var(--line);background:#050a10;padding:14px 16px;font-size:10px;color:var(--muted);margin-bottom:60px}
  .log div{display:grid;grid-template-columns:86px 1fr auto;gap:12px;padding:5px 0;border-bottom:1px dashed #183244}
  .log div:last-child{border-bottom:0}
  .log b{color:var(--cyan);font-weight:400}
  .log em{color:var(--lime);font-style:normal}
  footer{display:flex;justify-content:space-between;border-top:1px solid var(--line);padding:18px 0;font-size:9px;letter-spacing:.16em;color:var(--muted)}
  .reveal{opacity:0;transform:translateY(14px);transition:opacity var(--dur) var(--ease),transform var(--dur) var(--ease)}
  .reveal.on{opacity:1;transform:none}
  @media (max-width:860px){.hero{grid-template-columns:1fr}.cards{grid-template-columns:1fr}.strip{grid-template-columns:1fr}
    .strip div{border-right:0;border-bottom:1px solid var(--line)}.nav nav{display:none}}
  @media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}.reveal{opacity:1;transform:none}}

