patterns.css:
:root{
    --slate:#0f172a; --deep:#080d18; --steel:#94a3b8; --amber:#f59e0b; --text:#e8eef8;
    --muted:#93a4bd; --line:#243247; --ease:cubic-bezier(.2,.8,.2,1); --dur:560ms;
  }
  *{box-sizing:border-box}
  body{margin:0;background:var(--deep);color:var(--text);font-family:"Arial Narrow","Franklin Gothic Medium",Arial,sans-serif;line-height:1.5}
  h1,h2,h3{font-family:"Arial Narrow",Arial,sans-serif;font-weight:700;line-height:.98;letter-spacing:-.02em;margin:0;text-transform:uppercase}
  a{color:inherit;text-decoration:none}
  .wrap{width:min(1240px,94vw);margin:0 auto}
  .top{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:16px 0;border-bottom:1px solid var(--line)}
  .brand{display:flex;align-items:center;gap:9px;font-size:14px;letter-spacing:.18em;text-transform:uppercase}
  .brand svg{color:var(--amber)}
  .top nav{display:flex;gap:20px;font-size:9px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted)}
  .top nav a:hover{color:var(--amber)}
  .status{display:flex;align-items:center;gap:7px;border:1px solid var(--line);padding:6px 10px;font-size:8.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--amber)}
  .status i{width:6px;height:6px;background:var(--amber);border-radius:50%;box-shadow:0 0 10px var(--amber)}
  .board{display:grid;grid-template-columns:1.15fr .85fr;gap:0;border-bottom:1px solid var(--line);min-height:480px}
  .main{padding:36px 34px 30px 0;border-right:1px solid var(--line);position:relative;overflow:hidden}
  .main::before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,#24324744 1px,#0000 1px),linear-gradient(#24324744 1px,#0000 1px);background-size:58px 58px;mask-image:linear-gradient(90deg,#000,#0000 82%);pointer-events:none}
  .kicker{position:relative;display:inline-flex;align-items:center;gap:8px;font-size:8.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--amber);border-left:3px solid var(--amber);padding-left:9px;margin-bottom:14px}
  .main h1{position:relative;font-size:clamp(42px,6vw,86px);max-width:12ch}
  .main h1 span{color:var(--amber)}
  .main p{position:relative;max-width:44ch;color:var(--muted);font-size:13px;margin:16px 0 22px}
  .actions{position:relative;display:flex;gap:10px;flex-wrap:wrap}
  .btn{display:inline-flex;align-items:center;gap:8px;padding:11px 17px;font-size:9px;letter-spacing:.18em;text-transform:uppercase;transition:transform var(--dur) var(--ease),background var(--dur) var(--ease),color var(--dur) var(--ease)}
  .btn.solid{background:var(--amber);color:var(--deep)}
  .btn.solid:hover{transform:translateY(-2px);background:#fbbf24}
  .btn.line{border:1px solid var(--line);color:var(--text)}
  .btn.line:hover{border-color:var(--steel);transform:translateY(-2px)}
  .matrix{border-left:1px solid var(--line);padding:24px 0 24px 22px;display:flex;flex-direction:column;gap:12px}
  .matrix .head{display:flex;justify-content:space-between;font-size:8px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted);border-bottom:1px solid var(--line);padding-bottom:8px}
  .matrix .head b{color:var(--amber);font-weight:400}
  .cells{display:grid;grid-template-columns:repeat(4,1fr);gap:5px}
  .cell{aspect-ratio:1;border:1px solid var(--line);position:relative;background:#0b1322;transition:background var(--dur) var(--ease),border-color var(--dur) var(--ease)}
  .cell.on{background:#f59e0b1f;border-color:#f59e0b66}
  .cell.on::after{content:"";position:absolute;inset:38%;background:var(--amber);border-radius:50%;box-shadow:0 0 10px var(--amber)}
  .cell.hi{background:#f59e0b33;border-color:#f59e0b99}
  .legend{display:flex;justify-content:space-between;font-size:7.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}
  .layers{display:grid;grid-template-columns:repeat(3,1fr);border-bottom:1px solid var(--line)}
  .layer{padding:20px;border-right:1px solid var(--line);background:#0b1322;transition:background var(--dur) var(--ease),transform var(--dur) var(--ease)}
  .layer:last-child{border-right:0}
  .layer:hover{background:#101b2e;transform:translateY(-3px)}
  .layer .n{font-size:8.5px;letter-spacing:.2em;color:var(--amber);margin-bottom:10px}
  .layer h3{font-size:20px;margin-bottom:5px}
  .layer p{margin:0;font-size:11px;color:var(--muted)}
  .log{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid var(--line)}
  .log div{padding:14px 18px;border-right:1px solid var(--line);font-size:8.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}
  .log div:last-child{border-right:0}
  .log b{display:block;color:var(--amber);font-size:15px;letter-spacing:.02em;margin-top:3px}
  .quote{padding:30px 0;display:flex;justify-content:space-between;align-items:center;gap:24px;border-bottom:1px solid var(--line)}
  .quote blockquote{margin:0;font-size:clamp(18px,2.2vw,28px);line-height:1.25;text-transform:none;font-weight:700;max-width:24ch}
  .quote blockquote span{color:var(--amber)}
  .quote .sig{font-size:8.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted);white-space:nowrap}
  footer{display:flex;justify-content:space-between;padding:16px 0;font-size:8.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted)}
  .reveal{opacity:0;transform:translateX(-16px);transition:opacity var(--dur) var(--ease),transform var(--dur) var(--ease)}
  .reveal.on{opacity:1;transform:none}
  @media (max-width:900px){.board{grid-template-columns:1fr}.main{border-right:0;padding-right:0}.matrix{border-left:0;padding-left:0}
    .layers,.log{grid-template-columns:1fr}.layer,.log div{border-right:0;border-bottom:1px solid var(--line)}.top nav{display:none}}
  @media (prefers-reduced-motion:reduce){*{transition:none!important}.reveal{opacity:1;transform:none}}

