patterns.css:
:root{
    --paper:#f4f2ec; --ink:#1f2a24; --forest:#2d4a3e; --moss:#5f7a68;
    --clay:#b45309; --line:#d8d2c4; --ease:cubic-bezier(.16,1,.3,1); --dur:680ms;
  }
  *{box-sizing:border-box}
  body{margin:0;background:var(--paper);color:var(--ink);font-family:"Trebuchet MS","Segoe UI",sans-serif;line-height:1.55}
  h1,h2,h3{font-family:"Arial Black",Arial,sans-serif;line-height:.98;letter-spacing:-.04em;margin:0}
  a{color:inherit;text-decoration:none}
  .top{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:16px 30px;border-bottom:1px solid var(--line)}
  .brand{font-family:"Arial Black",Arial,sans-serif;font-size:18px;letter-spacing:-.03em;text-transform:uppercase}
  .top nav{display:flex;gap:22px;font-size:9.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--moss)}
  .top nav a:hover{color:var(--forest)}
  .top .bag{font-size:9px;letter-spacing:.18em;text-transform:uppercase;border:1px solid var(--forest);padding:8px 12px;color:var(--forest)}
  .table{display:grid;grid-template-columns:1fr 1fr;gap:0;border-bottom:1px solid var(--line)}
  .intro{padding:36px 30px 30px;border-right:1px solid var(--line)}
  .kicker{font-size:9px;letter-spacing:.28em;text-transform:uppercase;color:var(--clay)}
  .intro h1{font-size:clamp(44px,6vw,84px);margin:12px 0 14px;max-width:11ch;color:var(--forest)}
  .intro h1 em{font-style:normal;color:var(--clay)}
  .intro p{max-width:42ch;color:var(--moss);font-size:13px;margin:0 0 20px}
  .swatches{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;max-width:340px}
  .swatches div{height:64px;border:1px solid var(--line);position:relative;overflow:hidden}
  .swatches div:nth-child(1){background:#3d5c4c}
  .swatches div:nth-child(2){background:#c9a184}
  .swatches div:nth-child(3){background:#e7e2d4}
  .swatches div::after{content:"";position:absolute;inset:0;background:repeating-linear-gradient(45deg,#0000 0 8px,#f4f2ec1f 8px 9px)}
  .swatches span{position:absolute;left:5px;bottom:4px;color:#f4f2ec;font-size:7px;letter-spacing:.16em;text-transform:uppercase}
  .swatches div:nth-child(3) span{color:var(--forest)}
  .bench{padding:30px;display:flex;flex-direction:column;gap:0}
  .bench .head{display:flex;justify-content:space-between;align-items:end;border-bottom:2px solid var(--ink);padding-bottom:8px;margin-bottom:0}
  .bench .head h2{font-size:24px}
  .bench .head span{font-size:8.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--moss)}
  .step{display:grid;grid-template-columns:38px 1fr auto;gap:14px;align-items:baseline;padding:14px 0;border-bottom:1px solid var(--line);transition:padding var(--dur) var(--ease),background var(--dur) var(--ease)}
  .step:hover{background:#fbfaf6;padding-left:8px}
  .step .n{font-family:"Arial Black",Arial,sans-serif;font-size:18px;color:var(--clay)}
  .step h3{font-size:16px;margin-bottom:2px}
  .step p{margin:0;font-size:10.5px;color:var(--moss)}
  .step .time{font-size:8.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--moss);white-space:nowrap}
  .pieces{display:grid;grid-template-columns:repeat(3,1fr);border-bottom:1px solid var(--line)}
  .piece{padding:18px;border-right:1px solid var(--line);transition:background var(--dur) var(--ease)}
  .piece:last-child{border-right:0}
  .piece:hover{background:#fbfaf6}
  .piece .fig{height:150px;background:#e7e2d4;position:relative;overflow:hidden;margin-bottom:10px}
  .piece:nth-child(2) .fig{background:#dfe7dc}
  .piece:nth-child(3) .fig{background:#f0e2cf}
  .piece .fig::after{content:"";position:absolute;inset:0;background:repeating-linear-gradient(45deg,#0000 0 12px,#1f2a2410 12px 13px)}
  .piece h3{font-size:16px;margin-bottom:2px}
  .piece p{margin:0;font-size:10px;color:var(--moss)}
  .piece .price{display:block;margin-top:5px;font-size:9.5px;letter-spacing:.12em;color:var(--clay)}
  .note{display:grid;grid-template-columns:1fr 1fr;gap:30px;padding:26px 30px;border-bottom:1px solid var(--line)}
  .note blockquote{margin:0;font-family:Georgia,serif;font-size:clamp(20px,2.4vw,30px);line-height:1.3;color:var(--forest);font-style:italic}
  .note .facts{display:grid;grid-template-columns:1fr 1fr;gap:12px}
  .note .fact{border-top:1px solid var(--line);padding-top:8px}
  .note .fact b{display:block;font-family:"Arial Black",Arial,sans-serif;font-size:24px;color:var(--clay)}
  .note .fact span{font-size:8px;letter-spacing:.18em;text-transform:uppercase;color:var(--moss)}
  footer{display:flex;justify-content:space-between;padding:14px 30px;font-size:8.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--moss)}
  .reveal{opacity:0;transform:translateY(16px);transition:opacity var(--dur) var(--ease),transform var(--dur) var(--ease)}
  .reveal.on{opacity:1;transform:none}
  @media (max-width:860px){.table{grid-template-columns:1fr}.intro{border-right:0;border-bottom:1px solid var(--line)}
    .pieces{grid-template-columns:1fr}.piece{border-right:0;border-bottom:1px solid var(--line)}.note{grid-template-columns:1fr}.top nav{display:none}}
  @media (prefers-reduced-motion:reduce){*{transition:none!important}.reveal{opacity:1;transform:none}}

